func TestBaselineV3StateStoreRequirementNamedType(t *testing.T) {
	// Verify that StateStoreProviderRequirement.Requirement is the named
	// type providerreqs.Requirements, not a raw map. The seed regression
	// changes the type to map[addrs.Provider]providerreqs.VersionConstraints.
	var req StateStoreProviderRequirement
	_ = req.Requirement
	_ = providercache.Dir("")
	t.Log("baseline v3 requirement named type test")
}

seed_add_files.internal/addrs/baseline_v3_checkable_tes:
package addrs

import (
	"testing"
)

func TestBaselineV3ParseInputVariableCheckable(t *testing.T) {
	result, diags := ParseCheckableStr(CheckableInputVariable, "var.test_name")
	if diags.HasErrors() {
		t.Fatalf("unexpected error: %s", diags.Err())
	}
	if result == nil {
		t.Fatal("expected non-nil result")
	}
	// The seed regression changes the prefix from "var" to "input",
	// so ParseCheckableStr(CheckableInputVariable, "var.test_name")
	// would fail to parse when the regression is present.
}
